#!/bin/sh
# Print the three IP addresses that appear most often in access.log,
# one per line, most frequent first; ties broken by first appearance.
awk '
{
    ip = $1
    if (!(ip in count)) {
        first_seen[ip] = ++order[ip]
    }
    count[ip]++
}
END {
    n = 0
    for (ip in count) {
        lines[++n] = sprintf("%012d %012d %s", count[ip], first_seen[ip], ip)
    }
    # insertion sort: highest count first, then earliest first appearance
    for (i = 2; i <= n; i++) {
        key = lines[i]
        j = i - 1
        while (j >= 1 && lines[j] > key) {
            lines[j + 1] = lines[j]
            j--
        }
        lines[j + 1] = key
    }
    limit = (n < 3) ? n : 3
    for (i = 1; i <= limit; i++) {
        print lines[i]
    }
}' access.log | sed 's/^ *//' | awk '{print $3}'

#!/bin/sh
# Print the three IP addresses that appear most often in access.log,
# one per line, most frequent first; ties broken by first appearance.
awk '
{
    ip = $1
    if (!(ip in count)) {
        first_seen[ip] = ++n
    }
    count[ip]++
}
END {
    m = 0
    for (ip in count) {
        keys[++m] = sprintf("%012d", count[ip])
        ord[m]   = sprintf("%012d", first_seen[ip])
        name[m]  = ip
    }
    # insertion sort: highest count first, then earliest first appearance
    for (i = 2; i <= m; i++) {
        k = keys[i]; o = ord[i]; nm = name[i]
        j = i - 1
        while (j >= 1 && (keys[j] < k || (keys[j] == k && ord[j] > o))) {
            keys[j + 1] = keys[j]
            ord[j + 1]  = ord[j]
            name[j + 1] = name[j]
            j--
        }
        keys[j + 1] = k
        ord[j + 1]  = o
        name[j + 1] = nm
    }
    limit = (m < 3) ? m : 3
    for (i = 1; i <= limit; i++) print name[i]
}' access.log
